// Homepage search: a dropdown of every page and link on the site, ignoring case and accents.
// Reads SEARCH_INDEX from search-index.js (generated by _build/build.py).
// Browsers without the features below just never show the search box.
(function () {
  var slot = document.getElementById && document.getElementById('search');
  if (!slot || !window.SEARCH_INDEX || !document.querySelectorAll || !''.normalize || !document.addEventListener) return;

  function fold(s) { return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); }
  function byTitle(a, b) { return a.t.localeCompare(b.t, 'en', { sensitivity: 'base' }); }

  var entries = SEARCH_INDEX.map(function (e) { return { t: e.t, h: e.h, p: e.p, key: fold(e.t), trail: fold(e.p + ' ' + (e.k || '')) }; });

  slot.className = 'search';
  slot.innerHTML = '<input type="search" placeholder="search" aria-label="Search the site" autocomplete="off" spellcheck="false">'
    + '<div class="search-results" hidden></div>';
  var input = slot.firstChild;
  var list = slot.lastChild;
  var active = -1;

  function results(q) {
    var words = fold(q).split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    return entries.filter(function (e) {
      return words.every(function (w) { return e.key.indexOf(w) >= 0 || e.trail.indexOf(w) >= 0; });
    }).map(function (e) {
      var inTitle = words.every(function (w) { return e.key.indexOf(w) >= 0; });
      return { e: e, rank: e.key.indexOf(words[0]) === 0 ? 0 : inTitle ? 1 : 2 };
    }).sort(function (a, b) { return (a.rank - b.rank) || byTitle(a.e, b.e); }).map(function (r) { return r.e; });
  }

  function highlight(i) {
    var links = list.querySelectorAll('a');
    if (!links.length) return;
    active = (i + links.length) % links.length;
    for (var j = 0; j < links.length; j++) links[j].className = j === active ? 'active' : '';
    links[active].scrollIntoView({ block: 'nearest' });
  }

  function update() {
    var q = input.value.replace(/^\s+|\s+$/g, '');
    var found = results(q);
    list.innerHTML = '';
    active = -1;
    found.forEach(function (e) {
      var a = document.createElement('a');
      a.href = e.h;
      a.appendChild(document.createTextNode(e.t));
      if (e.p) {
        var trail = document.createElement('span');
        trail.className = 'search-trail';
        trail.appendChild(document.createTextNode(e.p));
        a.appendChild(trail);
      }
      list.appendChild(a);
    });
    if (q && !found.length) {
      var none = document.createElement('div');
      none.className = 'search-none';
      none.appendChild(document.createTextNode('nothing found'));
      list.appendChild(none);
    }
    list.hidden = !q;
  }

  input.addEventListener('input', update);
  input.addEventListener('focus', update);
  input.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowDown') { ev.preventDefault(); highlight(active + 1); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); highlight(active - 1); }
    else if (ev.key === 'Enter') {
      var target = list.querySelectorAll('a')[active < 0 ? 0 : active];
      if (target) { ev.preventDefault(); window.location.href = target.href; }
    } else if (ev.key === 'Escape') { list.hidden = true; input.blur(); }
  });
  document.addEventListener('click', function (ev) { if (!slot.contains(ev.target)) list.hidden = true; });
})();
